describe('External Links Open in New Tab', () => {
  beforeEach(() => {
    cy.visit('/page');
  });

  it('should open external links in a new tab', () => {
    // Verify the page loads
    cy.get('[data-testid="page-container"]').should('be.visible');

    // Click on an external link
    cy.get('[data-testid="external-link"]').click();

    // Verify a new tab/window is opened
    cy.window().then((win) => {
      expect(win.opener).to.exist;
    });

    // Verify the new tab has a different URL
    cy.window().then((win) => {
      expect(win.location.href).to.include('https://external-site.com');
    });

    // Verify the original tab is still open and functional
    cy.get('[data-testid="page-container"]').should('be.visible');
    cy.get('[data-testid="page-title"]').should('contain', 'Page Title');
  });

  it('should handle multiple external links and close the new tab', () => {
    // Click on the first external link
    cy.get('[data-testid="external-link-1"]').click();

    // Verify the first new tab opens
    cy.window().then((win) => {
      expect(win.opener).to.exist;
    });

    // Click on the second external link
    cy.get('[data-testid="external-link-2"]').click();

    // Verify the second new tab opens
    cy.window().then((win) => {
      expect(win.opener).to.exist;
    });

    // Close the first new tab
    cy.window().then((win) => {
      win.close();
    });

    // Verify the original tab is still open
    cy.get('[data-testid="page-container"]').should('be.visible');

    // Verify the second new tab is still open
    cy.window().then((win) => {
      expect(win.opener).to.exist;
    });

    // Verify the second new tab has the correct URL
    cy.window().then((win) => {
      expect(win.location.href).to.include('https://external-site.com/page2');
    });
  });
});
